// Wallet security, store identity and dedicated platform support.
let pendingListing=null;
listProduct=function(i){if(listed.includes(i)){toast('该商品已上架');return}let p=products[i];if(!p)return;pendingListing=i;document.getElementById('overlay').innerHTML=`<div class="modalback" onclick="if(event.target===this)cancelListing()"><div class="modal" role="dialog" aria-modal="true" aria-label="确认上架商品"><h2>确认上架商品</h2><div class="review-product"><div class="review-product-art">${art(p[4])}</div><div><h3>${esc(p[0])}</h3><p class="small">${esc(p[1])}</p></div></div><div class="info"><div><label>成本价</label><b>${money(p[3])}</b></div><div><label>零售价</label><b class="red">${money(p[2])}</b></div></div><div class="rule">确认将该商品上架至您的店铺？上架后可在「店铺管理」中查看。</div><div class="actions">${action('取消','cancelListing()')}${action('确认上架',`confirmListing(${i})`,true)}</div></div></div>`};
function cancelListing(){pendingListing=null;closeModal()}
function confirmListing(i){if(pendingListing!==i)return;pendingListing=null;if(!listed.includes(i)){listed.push(i);persistV2()}closeModal();render();toast('商品已上架至您的店铺')}
let walletSecurity=JSON.parse(localStorage.getItem('walletSecurityV1')||'null');
let shopProfile=JSON.parse(localStorage.getItem('shopProfileV1')||'null')||{name:'林先生的全球好物店',avatar:''};
// 商家编号数据槽：真实值由 api.js 用后端 merchant.id（JYM+10 位）回填；
// 静态稿首帧尚未拉数时保持空串，避免出现演示用的旧 MER 号。
let immutableShopId='';
async function copyShopId(){try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(immutableShopId)}else{throw Error('fallback')}toast('店铺ID已复制')}catch(e){let field=document.createElement('textarea'),focused=document.activeElement;field.value=immutableShopId;field.style.cssText='position:fixed;left:-9999px;top:0';document.body.appendChild(field);field.select();let copied=false;try{copied=document.execCommand('copy')}catch(error){}field.remove();if(focused&&focused.focus)focused.focus();toast(copied?'店铺ID已复制':'复制失败，请手动复制店铺ID')}}
let avatarDraft='',pendingWithdrawal=null,passwordBusy=false;
let supportMessages=JSON.parse(localStorage.getItem('supportMessagesV1')||'null')||[['them','您好，欢迎来到客服中心。充值、保证金、店铺及订单问题，都可以在这里咨询。','09:00']];
const originalCatalogue=catalogue,originalWallet=walletV2,originalRender=render;
function profileAvatar(className='shop-avatar'){return `<span class="${className}">${shopProfile.avatar?`<img src="${esc(shopProfile.avatar)}" alt="店铺头像">`:esc(shopProfile.name.slice(0,1))}</span>`}
catalogue=function(own){let content=originalCatalogue(own);if(!own)return content;let marker='<section class="card" style="margin-bottom:22px">';let summary=`<section class="card shop-profile-bar">${profileAvatar()}<div><h2>${esc(shopProfile.name)}</h2><p class="small">店铺 ID：${immutableShopId} ${action('复制店铺ID','copyShopId()')}</p></div>${action('编辑店铺资料','editShopProfile()')}</section>`;return content.replace(marker,summary+marker)};
function editShopProfile(){avatarDraft=shopProfile.avatar;modal('编辑店铺资料',`<form id="shopProfileForm" onsubmit="event.preventDefault();saveShopProfile()"><label class="field-label">店铺头像</label><div class="avatar-editor"><span id="avatarPreview">${profileAvatar()}</span><div><input type="file" id="shopAvatarInput" accept="image/png,image/jpeg,image/webp" onchange="chooseShopAvatar(this)" hidden>${action('上传头像',"document.getElementById('shopAvatarInput').click()")}${action('恢复默认',"avatarDraft='';document.getElementById('avatarPreview').innerHTML='<span class=\"shop-avatar\">店</span>'")}<p class="small">支持 JPG、PNG、WebP，最大2MB</p></div></div><label class="field-label" for="shopName">店铺名称</label><input id="shopName" value="${esc(shopProfile.name)}" maxlength="30" required${inputGuard('new-password')} style="width:100%"><label class="field-label" for="shopId">店铺 ID</label><input id="shopId" value="${immutableShopId}" readonly aria-readonly="true"${inputGuard()} style="width:100%;background:#f4f5f7;color:#929aa6"><p id="shopProfileError" class="small red" role="alert"></p></form>`,`<button class="primary" type="submit" form="shopProfileForm">保存修改</button>`)}
function chooseShopAvatar(input){let f=input.files[0];if(!f)return;let error=document.getElementById('shopProfileError');if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>2*1024*1024){error.textContent='请选择2MB以内的 JPG、PNG 或 WebP 图片';input.value='';return}let reader=new FileReader();reader.onload=()=>{avatarDraft=reader.result;document.getElementById('avatarPreview').innerHTML=`<span class="shop-avatar"><img src="${esc(avatarDraft)}" alt="新头像预览"></span>`;error.textContent=''};reader.readAsDataURL(f)}
function saveShopProfile(){let name=document.getElementById('shopName').value.trim(),error=document.getElementById('shopProfileError');if(!name||name.length>30){error.textContent='请输入1至30字的店铺名称';return}let next={name,avatar:avatarDraft};try{localStorage.setItem('shopProfileV1',JSON.stringify(next))}catch(e){error.textContent='头像存储失败，请使用更小的图片后重试';return}shopProfile=next;closeModal();render();toast('店铺资料已更新')}
walletV2=function(){let html=originalWallet();let security=`<section class="card wallet-security"><span class="security-icon">♧</span><div><h3>钱包密码 <span class="tag ${walletSecurity?'':'orange'}">${walletSecurity?'已设置':'未设置'}</span></h3><p class="small">${walletSecurity?'提现前需验证钱包密码，保护资金操作。':'您尚未设置钱包密码，请先设置后再申请提现。'}</p></div>${action(walletSecurity?'修改钱包密码':'设置钱包密码','setWalletPassword()',!walletSecurity)}</section>`;return html.replace('<div class="stats"',security+'<div class="stats"')};
async function passwordDigest(password,salt){let material=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),{name:'PBKDF2'},false,['deriveBits']);let bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:Uint8Array.from(salt),iterations:120000,hash:'SHA-256'},material,256);return Array.from(new Uint8Array(bits),x=>x.toString(16).padStart(2,'0')).join('')}
// 0mf-d：钱包密码 = 6 位数字 PIN。为屏蔽浏览器（Chrome）密码自动填充/保存：
// input 用 type="text" + CSS -webkit-text-security:disc（视觉圆点不变）+
// autocomplete="off" + spellcheck="false"，id 不含 password 字样，并打 data-wpin
// 供 closeModal 关闭时统一清值。Firefox 不支持 text-security，wpinGuard 对
// 非 WebKit 内核回退 type="password" autocomplete="new-password"。
function wpinGuard(){try{if(window.CSS&&CSS.supports&&CSS.supports('-webkit-text-security','disc'))return;document.querySelectorAll('#overlay [data-wpin]').forEach(function(i){i.type='password';i.setAttribute('autocomplete','new-password')})}catch(e){}}
function setWalletPassword(){modal(walletSecurity?'修改钱包密码':'设置钱包密码',`<form id="passwordForm" onsubmit="event.preventDefault();saveWalletPassword()">${walletSecurity?'<label class="field-label" for="oldWpin">当前钱包密码</label><input type="text" id="oldWpin" data-wpin="1" autocomplete="off" spellcheck="false" autocapitalize="off" autocorrect="off" inputmode="numeric" maxlength="6" required style="width:100%;-webkit-text-security:disc" placeholder="请输入当前钱包密码">':''}<label class="field-label" for="newWpin">${walletSecurity?'新钱包密码':'钱包密码'}</label><input type="text" id="newWpin" data-wpin="1" autocomplete="off" spellcheck="false" autocapitalize="off" autocorrect="off" minlength="6" maxlength="6" inputmode="numeric" pattern="[0-9]{6}" placeholder="请输入6位数字密码" required style="width:100%;-webkit-text-security:disc"><label class="field-label" for="confirmWpin">确认密码</label><input type="text" id="confirmWpin" data-wpin="1" autocomplete="off" spellcheck="false" autocapitalize="off" autocorrect="off" maxlength="6" inputmode="numeric" pattern="[0-9]{6}" placeholder="请再次输入密码" required style="width:100%;-webkit-text-security:disc"><p id="passwordError" class="small red" role="alert"></p><div class="rule">此密码用于提现验证，请妥善保管；忘记密码可联系平台客服重置。</div></form>`,`<button class="primary" form="passwordForm" type="submit" id="passwordSaveButton">保存密码</button>`);wpinGuard()}
async function saveWalletPassword(){if(passwordBusy)return;let pass=document.getElementById('newWalletPassword').value,confirm=document.getElementById('confirmWalletPassword').value,error=document.getElementById('passwordError');if(!/^\d{6}$/.test(pass)){error.textContent='钱包密码必须为6位数字';return}if(pass!==confirm){error.textContent='两次输入的密码不一致';return}passwordBusy=true;let button=document.getElementById('passwordSaveButton');button.disabled=true;try{if(walletSecurity){let old=document.getElementById('oldWalletPassword').value;if(await passwordDigest(old,walletSecurity.salt)!==walletSecurity.digest){error.textContent='当前钱包密码不正确';return}}let salt=Array.from(crypto.getRandomValues(new Uint8Array(16)));let security={salt,digest:await passwordDigest(pass,salt)};localStorage.setItem('walletSecurityV1',JSON.stringify(security));walletSecurity=security;closeModal();render();toast('钱包密码已设置')}catch(e){error.textContent='密码保存失败，请使用新版 Chrome 或 Edge 重试'}finally{passwordBusy=false;button.disabled=false}}
function withdrawField(id,label,placeholder,extra=''){return `<label class="field-label" for="${id}">${label}</label><input id="${id}" placeholder="${placeholder}" required${inputGuard('new-password')} style="width:100%" ${extra}>`}
withdrawModal=function(method='银行卡'){pendingWithdrawal=null;if(!walletSecurity){setWalletPassword();return}modal('申请提现',`<div class="withdraw-balance">可提现余额 <b>${money(balance)}</b></div><form id="withdrawForm" onsubmit="event.preventDefault();submitWithdraw()"><label class="field-label" for="withdrawMethod">提现方式</label><select id="withdrawMethod" onchange="withdrawModal(this.value)" style="width:100%"><option ${method==='银行卡'?'selected':''}>银行卡</option><option ${method==='U地址'?'selected':''}>U地址</option></select>${method==='银行卡'?withdrawField('withdrawBank','银行名称','请输入银行名称')+withdrawField('withdrawAccount','银行卡号','请输入银行卡号','inputmode="numeric"')+withdrawField('withdrawName','姓名','请输入收款人姓名')+withdrawField('withdrawBranch','银行支行名称','请输入银行支行名称')+withdrawField('withdrawBranchCode','支行编号','请输入支行编号'):withdrawField('withdrawAccount','U地址（USDT 收款地址）','请输入完整收款地址')+'<label class="field-label" for="withdrawNetwork">收款网络</label><select id="withdrawNetwork" style="width:100%"><option>TRC20</option><option>ERC20</option></select>'}${withdrawField('withdrawAmount','提现金额（CNY）','请输入提现金额',`type="number" min="0.01" max="${balance}" step="0.01"`)}<p id="withdrawError" class="red small" role="alert"></p><div class="rule">点击提现后需输入钱包密码。验证成功后提交平台审核，申请金额暂时冻结。</div></form>`,`<button class="primary" form="withdrawForm" type="submit">提现</button>`)};
submitWithdraw=function(){let val=id=>document.getElementById(id).value.trim(),method=val('withdrawMethod'),account=val('withdrawAccount'),amount=Number(val('withdrawAmount')),bank=method==='银行卡'?{name:val('withdrawBank'),holder:val('withdrawName'),branch:val('withdrawBranch'),code:val('withdrawBranchCode')}:null,error='';if(!walletSecurity){setWalletPassword();return}if(!Number.isFinite(amount)||amount<=0||amount>balance||Math.abs(amount*100-Math.round(amount*100))>0.00001)error='请输入不超过可用余额的有效金额，最多两位小数';else if(bank&&(!bank.name||!bank.holder||!bank.branch||!bank.code))error='请完整填写银行名称、姓名、支行名称及支行编号';else if(bank&&!/^\d{12,22}$/.test(account.replace(/\s/g,'')))error='请输入12至22位银行卡号';else if(!bank&&!/^[a-zA-Z0-9]{26,64}$/.test(account))error='请核实收款地址格式';if(error){document.getElementById('withdrawError').textContent=error;return}pendingWithdrawal={method,account,amount,bank,network:bank?'':val('withdrawNetwork')};verifyWithdrawalModal()};
function verifyWithdrawalModal(){let w=pendingWithdrawal;if(!w)return;modal('验证钱包密码',`<p class="small">本次申请提现</p><h2 class="red" style="margin:15px 0">${money(w.amount)}</h2><p class="small">收款方式：${w.method}　${esc(maskAccount(w))}</p><form id="withdrawPasswordForm" onsubmit="event.preventDefault();confirmWithdrawal()"><label class="field-label" for="withdrawPassword">钱包密码</label><input id="withdrawPassword" type="text" minlength="6" maxlength="6" inputmode="numeric" pattern="[0-9]{6}" autocomplete="off" spellcheck="false" autocapitalize="off" autocorrect="off" data-wpin="1" placeholder="请输入钱包密码" required style="width:100%;-webkit-text-security:disc"><p id="withdrawPasswordError" class="small red" role="alert"></p></form>`,`<button class="primary" id="withdrawConfirmButton" type="submit" form="withdrawPasswordForm">确认提现</button>`)}
async function confirmWithdrawal(){if(passwordBusy||!pendingWithdrawal)return;let error=document.getElementById('withdrawPasswordError'),pass=document.getElementById('withdrawPassword').value,button=document.getElementById('withdrawConfirmButton');if(!/^\d{6}$/.test(pass)){error.textContent='钱包密码必须为6位数字';return}passwordBusy=true;button.disabled=true;try{if(await passwordDigest(pass,walletSecurity.salt)!==walletSecurity.digest){error.textContent='钱包密码不正确，请重新输入';return}let w=pendingWithdrawal;if(!w||w.amount>balance){error.textContent='可用余额已变更，请重新申请';return}let time=new Date().toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false});withdrawals.unshift({...w,id:'WD'+Date.now(),state:'待审核',reason:'',date:time,history:[time+' 钱包密码验证通过，提交申请','申请金额已冻结，等待后台审核']});balance=Math.round((balance-w.amount)*100)/100;pendingWithdrawal=null;persistV2();closeModal();render();modal('提现申请成功',`<div class="success-icon">✓</div><p style="text-align:center">${money(w.amount)} 的提现申请已提交</p><div class="rule">钱包密码验证通过。申请状态：待审核。您可以在提现申请记录中查看处理进度。</div>`)}catch(e){error.textContent='验证失败，请重试'}finally{passwordBusy=false;button.disabled=false}}
const previousWithdrawDetail=withdrawDetail;
withdrawDetail=function(i){previousWithdrawDetail(i);let w=withdrawals[i];if(w.bank){let dialog=document.querySelector('#overlay .modal'),card=document.createElement('div');card.className='rule';card.innerHTML=`<b>银行收款信息</b><br>银行名称：${esc(w.bank.name)}<br>银行卡号：${esc(maskAccount(w))}<br>姓名：${esc(w.bank.holder)}<br>银行支行名称：${esc(w.bank.branch)}<br>支行编号：${esc(w.bank.code)}`;dialog.insertBefore(card,dialog.querySelector('.actions'))}};
function supportConversationButton(){return `<button class="conversation pinned ${activeConversation===-1?'chosen':''}" onclick="activeConversation=-1;render()"><span class="user-avatar support-avatar">客</span><span class="conversation-text"><b>客服中心</b><small>平台专属客服 · 单独联系</small></span></button>`}
chatPage=function(){let service=activeConversation===-1,c=service?{name:'客服中心',initial:'客',messages:supportMessages}:conversations[activeConversation],pi=service?null:contactProduct(c),p=service?null:products[pi];return head('消息中心','用户咨询与平台客服，集中沟通处理。')+`<div class="chat-shell"><section class="conversation-pane"><div class="conversation-head"><b>会话列表</b><span class="small">${conversations.length+1} 个会话</span></div>${supportConversationButton()}${conversations.map((v,i)=>`<button class="conversation ${i===activeConversation?'chosen':''}" onclick="activeConversation=${i};conversations[${i}].unread=0;persistV2();render()"><span class="user-avatar" style="background:${v.color}">${v.initial}</span><span class="conversation-text"><b>${esc(v.name)}</b><small>${esc(v.messages[v.messages.length-1][1])}</small></span>${v.unread?`<span class="unread">${v.unread}</span>`:''}</button>`).join('')}</section><section class="chat-pane"><div class="chat-title"><div><b>${esc(c.name)}</b><p class="small">${service?'平台客服专属会话':'商品咨询会话'}</p></div><span class="small">${service?'服务时间：09:00–21:00':`关联订单 ${c.order}`}</span></div>${service?'<div class="support-context">♧ 充值、保证金补缴、店铺管理、商品下架与订单问题，请在此咨询平台客服。<br><span class="small">客服中心用于充值、保证金与店铺沟通；买家咨询按商品来源单独列出。</span></div>':`<div class="chat-product-context"><div class="chat-product-art">${art(p[4])}</div><div><span class="small">用户通过此商品联系商家</span><h3>${p[0]}</h3><p class="small">商品ID：${window.FolioData.productId(pi)} · ${p[1]}</p></div><div class="chat-product-price"><b class="red">${money(p[2])}</b><span class="small">零售价</span></div>${action('商品详情',`productDetail(${pi})`)}</div>`}<div class="chat-history" id="chatHistory"><div class="chat-date">${service?'平台客服专属沟通记录':'用户会话记录'}</div>${c.messages.map(m=>`<div class="chat-message ${m[0]==='me'?'mine':''}"><span class="chat-miniavatar">${m[0]==='me'?'商':c.initial}</span><div><div class="bubble">${esc(m[1])}</div><time>${esc(m[2])}</time></div></div>`).join('')}</div><div class="chat-composer"><textarea id="chatInput" placeholder="输入回复内容…（Ctrl+Enter 发送）"${inputGuard()} onkeydown="if(event.ctrlKey&&event.key==='Enter'){event.preventDefault();sendChat()}"></textarea><div><span class="small">${service?'仅与平台客服联系':'请使用清晰、友好的沟通方式'}</span>${action('发送消息','sendChat()',true)}</div></div></section></div>`};
sendChat=function(){let el=document.getElementById('chatInput'),v=el.value.trim();if(!v){toast('请输入消息内容');return}let msg=['me',v,new Date().toLocaleTimeString('zh-CN',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit'})];if(activeConversation===-1){supportMessages.push(msg);localStorage.setItem('supportMessagesV1',JSON.stringify(supportMessages))}else{conversations[activeConversation].messages.push(msg);persistV2()}render();document.getElementById('chatInput').focus();let h=document.getElementById('chatHistory');h.scrollTop=h.scrollHeight};
support=function(){activeConversation=-1;closeModal();go(9)};
pages[5]=walletV2;pages[9]=chatPage;activeConversation=-1;
render=function(){originalRender();let account=document.querySelector('.topright');account.innerHTML=`<button onclick="go(10)">♧ 平台通知 <span class="red">●</span></button><button onclick="support()">♧ 联系客服</button><span style="color:#e2e5e9">│</span>${profileAvatar('avatar')}${action(esc(shopProfile.name)+'　⌄','editShopProfile()')}`};
render();

// Keep business data and validation messages; remove introductory/helper prose.
head=function(title,sub,actions=''){return `<div class="heading"><h1>${title}</h1>${actions}</div>`};
stat=function(label,num){return `<div class="card stat"><label>${label}</label><strong>${num}</strong></div>`};
function compactCopy(html){
 html=html.replace(/<div class="welcome-strip">[\s\S]*?<\/div><button[\s\S]*?<\/button><\/div>/g,'');
 html=html.replace(/<div class="bottomnote">[\s\S]*?<\/div>/g,'');
 html=html.replace(/<div class="banner">[\s\S]*?<\/div>/g,'');
 html=html.replace(/<div class="support-context">[\s\S]*?<\/div>/g,'');
 html=html.replace(/<section class="card" style="margin-top:20px"><h2>结算说明<\/h2>[\s\S]*?<\/section>/g,'');
 html=html.replace(/<div class="rule">([\s\S]*?)<\/div>/g,(whole,body)=>/本次发货扣款|扣款后钱包余额|处理过程|银行收款信息|商品描述|当前状态：|当前进度：/.test(body)?whole:'');
 html=html.replace(/<p class="small">(支持 JPG、PNG、WebP，最大2MB|店铺 ID 由平台分配，不可修改。|提现前需验证钱包密码，保护资金操作。)<\/p>/g,'');
 html=html.replace(/<p class="small" style="margin-top:14px">下方按钮仅用于原型演示后台审核结果，正式商家端仅展示审核进度。<\/p>/g,'');
 html=html.replace(/<p class="small">回复将显示在该条评价下方。当前为交互演示，记录保存在本地。<\/p>/g,'');
 html=html.replace(/<span class="small">(仅与平台客服联系|请使用清晰、友好的沟通方式)<\/span>/g,'');
 html=html.replace(/<p>保证金功能一经平台关闭，不能重新开启。[\s\S]*?<\/p>/g,'');
 html=html.replace(/<p>本页状态切换仅用于设计预览，实际规则由平台后台配置。<\/p>/g,'');
 return html;
}
const fullCopyRender=render;
render=function(){fullCopyRender();let app=document.getElementById('app');app.innerHTML=compactCopy(app.innerHTML)};
const fullCopyModal=modal;
modal=function(title,body,actions=''){fullCopyModal(title,compactCopy(body),actions)};
render();

const platformCategories=['奢侈品','电子数码','家用电器','女装','男装','箱包','美妆','鞋靴','户外用品','节日商品'];
