// JOYBUY-DEV OVERRIDE: 分页窗口化——页码过多时只渲染一行：首末页 + 当前页±2 + 省略号。
function pageWindow(pages,page,template){const list=[];const add=n=>list.push(template(n));if(pages<=7){for(let n=1;n<=pages;n++)add(n);return list.join('')}let start=Math.max(1,page-2),end=Math.min(pages,page+2);if(start===1)end=Math.min(pages,5);if(end===pages)start=Math.max(1,pages-4);if(start>1)add(1);if(start>2)list.push('<span class="page-gap" aria-hidden="true">…</span>');for(let n=start;n<=end;n++)add(n);if(end<pages-1)list.push('<span class="page-gap" aria-hidden="true">…</span>');if(end<pages-1)add(pages);return list.join('')}

// JOYBUY-DEV OVERRIDE: 3 位以上页码时给分页器加紧凑类，避免 4 位页码在按钮内换行。
