const beforeNewCatalogue=catalogue;
catalogue=function(own){if(own)return paginatedShopProducts();let all=products.slice(0,catalogueCount).map((p,i)=>[p,i]);let pagesCount=cataloguePages;let pageData=all;return head('商品上架中心','')+`<section class="card" style="margin-bottom:20px"><div class="category-selector"><b>商品品类</b><div>${['全部品类',...platformCategories].map(c=>action(c,`category='${c}';listingPage=1;render()`,category===c)).join('')}</div></div><div class="toolbar" style="margin:20px 0 0"><input id="query" value="${esc(search)}" placeholder="输入商品名称搜索"${inputGuard()}>${action('查询',"search=document.getElementById('query').value;listingPage=1;render()",true)}${action('重置',"search='';category='全部品类';listingPage=1;render()")}</div></section><div class="section-label"><b>${category==='全部品类'?'平台商品':category}</b><span>共 ${catalogueTotal} 件</span></div><div class="products">${pageData.map(([p,i])=>`<article class="card product"><button class="product-image" onclick="productDetail(${i})" aria-label="查看${esc(p[0])}详情">${art(p[4])}</button><div class="body"><button class="product-name" onclick="productDetail(${i})">${esc(p[0])}</button><p class="small">${p[1]} · SKU ${String(i+1).padStart(5,'0')}</p><div class="product-prices"><div><label>成本价</label><b>${money(p[3])}</b></div><div><label>零售价</label><b class="red">${money(p[2])}</b></div></div><div class="actions">${action('查看详情',`productDetail(${i})`)}${action(listed.includes(i)?'已上架':'上架商品',`listProduct(${i})`,true,listed.includes(i))}</div></div></article>`).join('')}</div>${!all.length?'<section class="card empty-state">暂无匹配商品</section>':''}<div class="${pagerClass(pagesCount,listingPage)}"><div>${action('上一页','listingPage--;render()',false,listingPage===1||catalogueLoading)}${pageWindow(pagesCount,listingPage,i=>action(String(i),`listingPage=${i};render()`,listingPage===i,catalogueLoading))}${action('下一页','listingPage++;render()',false,listingPage===pagesCount||catalogueLoading)}</div></div>`};
