submitWithdraw=function(){let val=id=>document.getElementById(id).value.trim(),method=val('withdrawMethod'),account=val('withdrawAccount'),amount=Number(val('withdrawAmount')),isBank=method==='银行卡',bank=isBank?{name:val('withdrawBank'),holder:val('withdrawName'),branch:val('withdrawBranch'),code:val('withdrawBranchCode')}:null,coin=isBank?'':val('withdrawCoin'),network=isBank?'':val('withdrawNetwork'),error='';if(!Number.isFinite(amount)||amount<=0||Math.abs(amount*100-Math.round(amount*100))>0.00001)error='请输入大于0的提现金额，最多两位小数';else if(amount>balance)error='提现金额超出钱包余额，当前可提现余额为 '+money(balance);else if(isBank&&(!bank.name||!bank.holder||!bank.branch||!bank.code))error='请完整填写银行名称、姓名、支行名称及支行编号';else if(isBank&&!/^\d{12,22}$/.test(account.replace(/\s/g,'')))error='请输入12至22位银行卡号';else if(!isBank&&!['ETH','USDT'].includes(coin))error='请选择币种';else if(!isBank&&!['ERC-20','TRC-20'].includes(network))error='请选择链类型';else if(!isBank&&coin==='ETH'&&network!=='ERC-20')error='ETH 请选择 ERC-20 链';else if(!isBank&&network==='ERC-20'&&!/^0x[a-fA-F0-9]{40}$/.test(account))error='请输入正确的 ERC-20 钱包地址';else if(!isBank&&network==='TRC-20'&&!/^T[1-9A-HJ-NP-Za-km-z]{33}$/.test(account))error='请输入正确的 TRC-20 钱包地址';if(error){document.getElementById('withdrawError').textContent=error;return}if(!walletSecurity){setWalletPassword();return}pendingWithdrawal={method,account,amount,bank,coin,network};verifyWithdrawalModal()};
