function queryDates(kind){let from=document.getElementById(kind+'From').value,to=document.getElementById(kind+'To').value;if(from&&to&&from>to){toast('开始日期不能晚于结束日期');return}if(kind==='order'){queryOrder=document.getElementById('opsOrderSearch')?.value.trim()||'';orderFrom=from;orderTo=to}else{fundQuery=document.getElementById('opsFundSearch').value.trim();fundFrom=from;fundTo=to;fundKind=document.getElementById('opsFundType').value}render()}
function selectedOrders(){return orders.filter(o=>(orderFilter==='全部订单'||orderGroup(o)===orderFilter)&&(!queryOrder||(o[0]+' '+products[o[1]][0]).toLowerCase().includes(queryOrder.toLowerCase()))&&dateInRange(String(o.orderMeta?.date||''),orderFrom,orderTo))}
orderPage=function(){let rows=orders.slice();return head('订单管理','')+`<section class="card">${chips(['全部订单','待处理','已发货','已完成'],orderFilter,i=>`orderFilter=['全部订单','待处理','已发货','已完成'][${i}];render()`)}<div class="toolbar"><input id="opsOrderSearch" placeholder="订单号 / 商品名称" value="${esc(queryOrder)}"${inputGuard()}><input type="date" id="orderFrom" aria-label="开始日期" value="${orderFrom}"${inputGuard()}><span>至</span><input type="date" id="orderTo" aria-label="结束日期" value="${orderTo}"${inputGuard()}>${action('查询',"queryDates('order')",true)}${action('重置',"queryOrder='';orderFrom='';orderTo='';render()")}</div>${table(['订单号','商品','数量','下单时间','订单金额','成本价','状态','操作'],rows.map(o=>[o[0],products[o[1]][0],qty(o),(o.orderMeta?esc(o.orderMeta.date):'2026-10-31 '+o[2]),money(totalPrice(o)),money(totalCost(o)),opsTag(orderGroup(o)),`<div class="table-actions">${action('查看详情',`selected=${orders.indexOf(o)};go(4)`)}${unshipped(o)?action('发货',`selected=${orders.indexOf(o)};confirmShip()`,true):''}</div>`]))}${!rows.length?'<p class="empty-state">暂无匹配订单</p>':''}<div class="${pagerClass(ordersPages,ordersPageNo)}"><div>${action('上一页','ordersPageNo--;render()',false,ordersPageNo===1||ordersLoading)}${pageWindow(ordersPages,ordersPageNo,i=>action(String(i),`ordersPageNo=${i};render()`,ordersPageNo===i,ordersLoading))}${action('下一页','ordersPageNo++;render()',false,ordersPageNo===ordersPages||ordersLoading)}</div></div></section>`};
function exportOrders(){downloadCsv('订单查询记录',['订单号','商品','数量','下单时间','金额','成本','状态'],selectedOrders().map(o=>[o[0],products[o[1]][0],qty(o),'2026-10-31 '+o[2],totalPrice(o),totalCost(o),orderGroup(o)]))}
function auditShipping(order,result,amount,detail){shippingAudit.unshift({time:opsNow(),order,result,amount,detail});opsSave('shippingAuditV2',shippingAudit)}
const opsConfirmShip=confirmShip,opsShip=ship;
confirmShip=function(){let o=orders[selected];if(opsScenario!=='接单中'){auditShipping(o[0],'店铺受限',0,opsScenario+'，未扣款');toast('当前店铺状态暂不支持发货，请联系客服');return}if(unshipped(o)&&balance<totalCost(o))auditShipping(o[0],'余额不足',0,'钱包校验失败，未扣款');opsConfirmShip()};
ship=function(i){let o=orders[i];if(opsScenario!=='接单中'){toast('店铺受限，发货未提交');return}if(!unshipped(o)||sent.includes(o[0])){toast('该订单已发货，请勿重复提交');return}if(balance<totalCost(o)){auditShipping(o[0],'余额不足',0,'确认前余额变化，未扣款');toast('钱包余额不足，请充值后重试');return}let before=balance;opsShip(i);if(sent.includes(o[0])){auditShipping(o[0],'发货成功',balance-before,'流水 SH'+o[0]+' · 物流 LG'+o[0]);render()}};
const opsListProduct=listProduct;
listProduct=function(i){if(opsScenario!=='接单中'){toast('当前店铺状态暂不支持上架');return}opsListProduct(i)};
const opsConfirmListing=confirmListing;
confirmListing=function(i){if(opsScenario!=='接单中'){toast('店铺状态已变更，暂不支持上架');return}opsConfirmListing(i)};
function setOpsScenario(s){opsScenario=s;sealed=s!=='接单中';render()}
const beforeStoreOps=catalogue;
catalogue=function(own){return beforeStoreOps(own)};
function applyUnseal(){opsScenario='解封审核中';sealed=true;render();toast('解封申请已提交，等待平台审核')}
function requestWalletReset(){if(resetRequest?.state==='可重置'){resetPasswordForm();return}modal('找回钱包密码',`<div class="info"><div><label>店铺名称</label>${esc(shopProfile.name)}</div><div><label>店铺 ID</label>${immutableShopId}</div></div>${resetRequest?`<div class="ops-alert">申请单号：${resetRequest.id}<br>当前状态：${resetRequest.state}${resetRequest.reason?'<br>原因：'+esc(resetRequest.reason):''}</div>${operationRows(resetRequest.history)}`:''}`,`${action('联系客服','support()')}${!resetRequest||resetRequest.state==='已打回'?action('提交找回申请','submitResetRequest()',true):''}`)}
function submitResetRequest(){resetRequest={id:'PR'+Date.now(),state:'待审核',history:[[opsNow(),'提交找回申请','等待平台核实店铺资料']]};opsSave('resetRequestV2',resetRequest);closeModal();render();requestWalletReset()}
function approveReset(approved){if(!resetRequest||resetRequest.state!=='待审核')return;resetRequest.state=approved?'可重置':'已打回';resetRequest.reason=approved?'':'店铺核验资料不完整，请联系客服补充';resetRequest.history.push([opsNow(),approved?'平台核实通过':'平台打回',resetRequest.reason]);opsSave('resetRequestV2',resetRequest);render()}
function resetPasswordForm(){modal('重置钱包密码',`<form id="resetWalletForm" onsubmit="event.preventDefault();completeWalletReset()"><label class="field-label" for="resetPass">新钱包密码</label><input type="text" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" id="resetPass" data-wpin="1" autocomplete="off" spellcheck="false" autocapitalize="off" autocorrect="off" required placeholder="6位数字" style="width:100%;-webkit-text-security:disc"><label class="field-label" for="resetPassAgain">确认密码</label><input type="text" inputmode="numeric" maxlength="6" id="resetPassAgain" data-wpin="1" autocomplete="off" spellcheck="false" autocapitalize="off" autocorrect="off" required style="width:100%;-webkit-text-security:disc"><p id="resetPassError" class="red small" role="alert"></p></form>`,`<button type="submit" form="resetWalletForm" class="primary">重置密码</button>`);wpinGuard()}
async function completeWalletReset(){if(resetRequest?.state!=='可重置')return;let p=document.getElementById('resetPass').value,c=document.getElementById('resetPassAgain').value,error=document.getElementById('resetPassError');if(!/^\d{6}$/.test(p)||p!==c){error.textContent='请输入相同的6位数字密码';return}if(passwordBusy)return;passwordBusy=true;try{let salt=Array.from(crypto.getRandomValues(new Uint8Array(16)));walletSecurity={salt,digest:await passwordDigest(p,salt)};opsSave('walletSecurityV1',walletSecurity);passwordGuard={failures:0,until:0};opsSave('passwordGuardV2',passwordGuard);resetRequest.state='已完成';resetRequest.history.push([opsNow(),'密码重置完成','']);opsSave('resetRequestV2',resetRequest);closeModal();render();toast('钱包密码已重置')}finally{passwordBusy=false}}
const beforePasswordForm=setWalletPassword;
setWalletPassword=function(){beforePasswordForm();let actions=document.querySelector('#overlay .actions');if(walletSecurity&&actions){let button=document.createElement('button');button.textContent='忘记密码';button.onclick=requestWalletReset;actions.prepend(button)}};
const beforeGuardWithdrawal=confirmWithdrawal;
confirmWithdrawal=async function(){if(passwordBusy||!pendingWithdrawal)return;let error=document.getElementById('withdrawPasswordError');if(Date.now()<passwordGuard.until){error.textContent='钱包密码已锁定，请15分钟后重试或找回密码';return}if(passwordGuard.until){passwordGuard={failures:0,until:0}}let count=withdrawals.length;await beforeGuardWithdrawal();if(withdrawals.length>count){passwordGuard={failures:0,until:0}}else if(error.textContent.includes('不正确')){passwordGuard.failures++;if(passwordGuard.failures>=5){passwordGuard.until=Date.now()+15*60000;error.textContent='连续输错5次，已锁定15分钟'}}opsSave('passwordGuardV2',passwordGuard)};
function opsPayouts(){return [...withdrawals.map(w=>({...w,state:w.state==='已通过'?'已到账':w.state,net:w.net??w.amount,fee:w.fee??0,frozen:['待审核','审核通过','转账中'].includes(w.state)?w.amount:0})),...payoutExamples]}
function payoutDetail(id){let w=opsPayouts().find(w=>w.id===id);if(!w)return;modal('提现处理明细',`<p class="small">${esc(w.id)} · ${esc(w.date)}</p><div class="info"><div><label>当前状态</label>${opsTag(w.state)}</div><div><label>申请金额</label>${money(w.amount)}</div><div><label>冻结金额</label>${money(w.frozen||0)}</div><div><label>手续费</label>${money(w.fee||0)}</div><div><label>应付净额</label>${money(w.net??w.amount)}</div><div><label>实际到账金额</label>${money(w.state==='已到账'?(w.net??w.amount):0)}</div><div><label>已退回金额</label>${money(/打回|失败/.test(w.state)?w.amount:0)}</div><div><label>收款方式</label>${esc(w.method)} ${esc(w.coin||'')} ${esc(w.network||'')}</div><div><label>收款账号</label>${esc(maskAccount(w))}</div></div>${w.chainAmount?`<div class="ops-alert">${esc(w.chainAmount)}<br>示例结算快照：1 USDT = ¥7.20</div>`:''}${w.reason?`<div class="ops-alert danger">${esc(w.reason)}</div>`:''}${w.reference?`<p>${esc(w.reference)}</p>`:''}${w.bank?`<div class="info"><div><label>银行</label>${esc(w.bank.name)}</div><div><label>姓名</label>${esc(w.bank.holder)}</div><div><label>支行 / 编号</label>${esc(w.bank.branch)} / ${esc(w.bank.code)}</div></div>`:''}${operationRows(w.history.map(h=>[h,'','']))}`)}
function allFundRows(){return [
 ...sent.map(id=>{let o=orders.find(x=>x[0]===id);return {time:(shipmentDates[id]||'未知日期')+' 10:00',type:'发货扣款',id:'SH'+id,order:id,amount:-totalCost(o),state:'已完成'}}),
 {time:'2026-11-02 10:10',type:'订单回款',id:'FL202611020001',order:'HW202610310083',amount:239,state:'已完成'},
 {time:'2026-11-02 09:15',type:'充值入账',id:'FL202611020002',order:'—',amount:10000,state:'已完成'},
 {time:'2026-11-01 09:40',type:'发货扣款',id:'SH202611010084',order:'HW202610310084',amount:-130,state:'已完成'},
 {time:'2026-11-01 16:00',type:'平台处罚扣款',id:'PF202611010002',order:'—',amount:-500,state:'保证金账户'},
 ...opsPayouts().map(w=>({time:w.date,type:'提现记录',id:w.id,order:'—',amount:/失败|打回/.test(w.state)?0:-w.amount,state:w.state}))
 ]}
function selectedFunds(){return allFundRows().filter(r=>(fundKind==='全部类型'||r.type===fundKind)&&(!fundQuery||(r.id+' '+r.order).includes(fundQuery))&&dateInRange(r.time,fundFrom,fundTo))}
function exportFunds(){downloadCsv('资金查询记录',['时间','类型','流水号','订单号','金额','状态'],selectedFunds().map(r=>[r.time,r.type,r.id,r.order,r.amount,r.state]))}
function profitRecords(){let rows=orders.filter(o=>!unshipped(o)).map(o=>{let d=shipmentDates[o[0]]||historicalShipmentDates[o[0]]||'未知日期';return [o[0],d,qty(o),money(totalPrice(o)),money(totalCost(o)),money(totalPrice(o)-totalCost(o)),d===businessDay()?'计入今日':'非今日']});modal('收益核对记录',table(['订单号','发货日期','数量','零售合计','成本合计','预计毛利','统计'],rows)+`<div class="ops-alert">当日预计毛利：${money(todayProfit())}<br>示例调整记录：HW202610290048 售后退款 −¥129.00；PF202611010002 平台处罚 −¥500.00（保证金）。调整记录单列，不计入当日发货毛利。</div>`)}
function walletOperations(){let funds=selectedFunds(),payouts=opsPayouts(),frozen=payouts.reduce((s,w)=>s+(w.frozen||0),0);return head('钱包管理','',`<div class="table-actions">${action('联系客服充值','support()')}${action('申请提现','withdrawModal()',true)}</div>`)+`<section class="card wallet-security"><div><h3>钱包密码 ${opsTag(walletSecurity?'已设置':'未设置')}</h3>${!walletSecurity?'<p class="small">请先设置6位数字钱包密码</p>':''}${passwordGuard.until>Date.now()?'<p class="red small">密码已锁定，请稍后重试或找回密码</p>':''}${resetRequest?`<p class="small">密码找回：${resetRequest.state}</p>`:''}</div><div class="table-actions">${action(walletSecurity?'修改钱包密码':'设置钱包密码','setWalletPassword()')}${action('找回密码','requestWalletReset()')}</div></section><div class="stats" style="grid-template-columns:repeat(4,1fr)">${stat('当前钱包余额',money(balance))}${stat('冻结金额',money(frozen))}${stat('今日回款',money(allFundRows().filter(r=>r.type==='订单回款'&&r.time.slice(0,10)===businessDay()).reduce((s,r)=>s+r.amount,0)))}${stat('今日新增收益',money(todayProfit()))}</div><div class="toolbar">${action('收益核对记录','profitRecords()')}</div><section class="card"><div class="cardhead"><h2>提现申请记录</h2><span class="tag gray">包含示例历史记录</span></div>${table(['单号 / 时间','方式','申请金额','冻结金额','状态','操作'],payouts.map(w=>[w.id+'<br>'+w.date,esc(w.method),money(w.amount),money(w.frozen||0),opsTag(w.state),action('处理明细',`payoutDetail('${w.id}')`)]))}</section><section class="card ops-block"><div class="cardhead"><h2>资金明细</h2></div><div class="toolbar"><input id="opsFundSearch" value="${esc(fundQuery)}" placeholder="流水号 / 订单号"><select id="opsFundType">${['全部类型','充值入账','发货扣款','订单回款','提现记录','平台处罚扣款'].map(t=>`<option ${fundKind===t?'selected':''}>${t}</option>`).join('')}</select><input type="date" id="fundFrom" aria-label="资金开始日期" value="${fundFrom}"><input type="date" id="fundTo" aria-label="资金结束日期" value="${fundTo}">${action('查询',"queryDates('fund')",true)}${action('重置',"fundQuery='';fundKind='全部类型';fundFrom='';fundTo='';render()")}</div>${table(['时间','类型','流水号','订单号','金额','状态'],funds.map(r=>[r.time,r.type,r.id,`<b class="${r.type==='订单回款'?'red':''}">${r.order}</b>`,money(r.amount),opsTag(r.state)]))}${!funds.length?'<div class="empty-state">暂无匹配记录</div>':''}</section>`}
function afterRecord(i){let r=afterRows[i];return afterAudit[r.id]||(afterAudit[r.id]={history:[],proof:[],result:''})}
handleAfter=function(i){let r=afterRows[i],a=afterRecord(i);modal('售后处理详情',`<p class="small">${r.id} · ${r.order}</p><h3>${esc(r.issue)}</h3><div class="info"><div><label>状态</label>${opsTag(r.state)}</div><div><label>当前进度</label>${esc(r.progress)}</div></div><h3>凭证</h3><div class="proof-list">${a.proof.map((p,j)=>p.sample?action(p.name,`showSampleProof()`):`<a href="${esc(p.data)}" target="_blank" rel="noopener"><img src="${esc(p.data)}" alt="售后凭证 ${j+1}"></a>`).join('')||'<span class="small">暂无凭证</span>'}</div>${r.state!=='已完成'?`<label class="field-label">上传凭证</label><input type="file" accept="image/png,image/jpeg,image/webp" onchange="addAfterProof(${i},this)"><label class="field-label" for="afterReply">处理说明</label><textarea id="afterReply" style="width:100%;height:75px" placeholder="填写处理依据或最终结果"${inputGuard()}></textarea><p id="afterError" class="red small" role="alert"></p>`:''}<h3>处理记录</h3>${operationRows(a.history)}${a.result?`<div class="ops-alert">处理结果：${esc(a.result)}</div>`:''}`,r.state==='已完成'?'':action('更新进度',`updateAfter(${i},false)`)+action('申请平台介入',`escalateAfter(${i})`)+action('完成处理',`updateAfter(${i},true)`,true))};
function showSampleProof(){modal('包装破损凭证（示例）',`<div class="proof-sample"><div>📦</div><b>外包装右侧压损</b><p>示例凭证说明 · 客户上传于2026-11-01 11:10</p></div>`)}
function addAfterProof(i,input){let f=input.files[0];if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>1024*1024){toast('请选择1MB以内图片');return}let reader=new FileReader();reader.onload=()=>{let a=afterRecord(i);a.proof.push({name:f.name,data:reader.result});try{opsSave('afterAuditV2',afterAudit);handleAfter(i)}catch(e){a.proof.pop();toast('凭证保存失败，请缩小图片')}};reader.readAsDataURL(f)}
updateAfter=function(i,done){let v=document.getElementById('afterReply').value.trim();if(!v){document.getElementById('afterError').textContent='请填写处理说明';return}let r=afterRows[i],a=afterRecord(i);r.state=done?'已完成':'处理中';r.progress=v;a.history.push([opsNow(),done?'商家完成处理':'商家更新进度',v]);if(done)a.result=v;opsSave('afterAuditV2',afterAudit);opsSave('afterRowsV2',afterRows);render();handleAfter(i)};
function escalateAfter(i){let v=document.getElementById('afterReply').value.trim();if(!v){document.getElementById('afterError').textContent='请填写申请介入的原因';return}let r=afterRows[i],a=afterRecord(i);r.state='平台介入中';r.progress='等待平台核实';a.history.push([opsNow(),'申请平台介入',v]);opsSave('afterAuditV2',afterAudit);opsSave('afterRowsV2',afterRows);render();handleAfter(i)}
afterRows=opsLoad('afterRowsV2',afterRows);
const oldAddFollowers=addFollowers;
addFollowers=function(){let before=followerState.total,n=Number(document.getElementById('followerIncrement').value);oldAddFollowers();if(followerState.total!==before){followerAudit.unshift({time:opsNow(),operator:'平台运营（演示）',amount:n,total:followerState.total,reason:'手动新增'});opsSave('followerAuditV2',followerAudit);render()}};
const opsAdmin=renderFollowerAdmin;
renderFollowerAdmin=function(){opsAdmin();if(!isPlatformAdmin())return;let content=document.querySelector('#platformAdminPanel .admin-content');content.insertAdjacentHTML('beforeend',`<section class="card ops-block"><h2>关注调整记录</h2>${table(['时间','操作人','新增','调整后总数','原因'],followerAudit.map(a=>[a.time,a.operator,'+'+a.amount,a.total,a.reason]))}</section><section class="card ops-block"><h2>钱包密码找回审核</h2>${resetRequest?`<p>${resetRequest.id} · ${resetRequest.state}</p>${operationRows(resetRequest.history)}${resetRequest.state==='待审核'?`<div class="table-actions">${action('核实通过','approveReset(true)',true)}${action('打回','approveReset(false)')}</div>`:''}`:'<p class="small">暂无申请</p>'}</section>`)};
function showFollowerAudit(){modal('关注变动记录',table(['时间','新增','总数','原因'],followerAudit.map(a=>[a.time,'+'+a.amount,a.total,a.reason])))}
function processPayout(id,next){let actual=withdrawals.find(w=>w.id===id),w=actual||payoutExamples.find(w=>w.id===id);if(!w)return;let allowed={'待审核':['审核通过','已打回'],'审核通过':['转账中'],'转账中':['已到账','转账失败']};if(!(allowed[w.state]||[]).includes(next))return;w.state=next;w.history.push(opsNow()+' '+next);if(/打回|失败/.test(next)){w.reason=next==='已打回'?'收款资料不完整，请补充后重新申请':'收款渠道返回失败，请核对收款账户';w.history.push(opsNow()+' '+money(w.amount)+'已解冻退回');if(actual)balance=Math.round((balance+w.amount)*100)/100;w.frozen=0}else if(next==='已到账'){w.frozen=0}else{w.frozen=w.amount}persistV2();opsSave('payoutExamplesV2',payoutExamples);render()}
const opsAdminWithReset=renderFollowerAdmin;
renderFollowerAdmin=function(){opsAdminWithReset();if(!isPlatformAdmin())return;let html=table(['单号','金额','状态','演示处理'],opsPayouts().map(w=>[w.id,money(w.amount),opsTag(w.state),w.state==='待审核'?action('审核通过',`processPayout('${w.id}','审核通过')`)+action('打回',`processPayout('${w.id}','已打回')`):w.state==='审核通过'?action('开始转账',`processPayout('${w.id}','转账中')`):w.state==='转账中'?action('确认到账',`processPayout('${w.id}','已到账')`)+action('转账失败',`processPayout('${w.id}','转账失败')`):'—']));document.querySelector('#platformAdminPanel .admin-content').insertAdjacentHTML('beforeend','<section class="card ops-block"><h2>提现处理演示</h2>'+html+'</section>')};
const completeVerifyWithdrawal=verifyWithdrawalModal;
verifyWithdrawalModal=function(){let w=pendingWithdrawal;if(!w)return;if(!w.bank){w.fee=w.network==='ERC-20'?12:10;if(w.amount<=w.fee){pendingWithdrawal=null;modal('提现金额不足',`<p>申请金额需要大于示例手续费 ${money(w.fee)}</p>`);return}w.net=Math.round((w.amount-w.fee)*100)/100;w.rate=w.coin==='ETH'?24000:7.2;w.chainAmount=(w.net/w.rate).toFixed(w.coin==='ETH'?6:2)+' '+w.coin+'（示例结算快照）'}completeVerifyWithdrawal();if(w.coin){let card=document.createElement('div');card.className='ops-alert';card.innerHTML=`手续费：${money(w.fee)}<br>应付净额：${money(w.net)}<br>预计到账：${esc(w.chainAmount)}<br>示例报价：1 ${esc(w.coin)} = ${money(w.rate)}`;let dialog=document.querySelector('#overlay .modal');dialog.insertBefore(card,dialog.querySelector('form'))}};
const completeDeposit=depositV2;
