let admissionPolicy=null;
function importAdmissionPolicy(){if(typeof location==='undefined'||!location.hash.startsWith('#admission='))return false;try{let p=JSON.parse(decodeURIComponent(location.hash.slice(11)));if(!p||!/^(?:MER\d+|JYM[A-Z0-9]{10})$/i.test(p.id)||typeof p.approved!=='boolean'||typeof p.depositEnabled!=='boolean'||!Number.isFinite(p.required)||p.required<0||!Number.isFinite(p.balance)||!Number.isFinite(p.wallet)||p.wallet<0||typeof p.name!=='string')return false;if(p.status==='解封审核中')p.status='已封店';admissionPolicy=p;immutableShopId=p.id;shopProfile={name:p.name,avatar:''};balance=p.wallet;enabled=p.approved&&p.depositEnabled;opsScenario=['待缴保证金'].includes(p.status)?'接单中':p.status;sealed=['已封店','解封审核中'].includes(p.status);return true}catch(e){return false}}
function admissionOpen(){return !admissionPolicy||(admissionPolicy.approved&&admissionPolicy.status==='接单中'&&(!admissionPolicy.depositEnabled||(admissionPolicy.initialDepositPaid?true:admissionPolicy.balance>=admissionPolicy.required)))}
function admissionCanFulfill(){return !admissionPolicy||(admissionPolicy.approved&&!['已封店','解封审核中'].includes(admissionPolicy.status))}
function admissionBlock(){modal('店铺尚未满足经营条件',`<div class="info"><div><label>店铺状态</label>${esc(admissionPolicy?.status||opsScenario)}</div><div><label>待缴保证金</label>${money(admissionPolicy?.depositEnabled?Math.max(0,admissionPolicy.required-admissionPolicy.balance):0)}</div></div>`,action('联系客服','support()',true))}
const admissionList=listProduct,admissionConfirmListing=confirmListing,admissionShip=ship,admissionConfirmShip=confirmShip,admissionGo=go,admissionRender=render;
listProduct=function(i){if(!admissionOpen()){admissionBlock();return}admissionList(i)};
confirmListing=function(i){if(!admissionOpen()){admissionBlock();return}admissionConfirmListing(i)};
ship=function(i){if(!admissionCanFulfill()){admissionBlock();return}admissionShip(i)};
confirmShip=function(){if(!admissionCanFulfill()){admissionBlock();return}admissionConfirmShip()};
go=function(i){if(admissionPolicy&&i===6&&(!admissionPolicy.approved||!admissionPolicy.depositEnabled)){toast('该店铺未启用保证金');return}admissionGo(i)};
