render=function(){admissionRender();if(!admissionPolicy)return;if(!admissionPolicy.approved||!admissionPolicy.depositEnabled){let nav=document.getElementById('nav');nav.innerHTML=nav.innerHTML.replace(/<button[^>]*onclick="go\(6\)"[\s\S]*?<\/button>/g,'')}let app=document.getElementById('app');if(admissionPolicy.status==='已封店'){let reason=admissionPolicy.closureReason||(admissionPolicy.closureCauses?.deposit?'保证金余额为0或负数，请联系客服补缴保证金，并由客服手动解封。':'订单超时未处理，请联系客服解封。');app.innerHTML=app.innerHTML.replace('原因：订单超过履约时限未处理。暂停上架与发货。',esc(reason));}app.innerHTML=app.innerHTML.replace(/<details class="ops-demo">[\s\S]*?<\/details>/g,'');if(current===0)app.innerHTML=app.innerHTML.replace(/<div class="card stat"><label>店铺状态<\/label>[\s\S]*?<\/strong><\/div>/,stat('店铺状态',`<span style="font-size:19px">${esc(admissionPolicy.status)}</span>`));if(current===0&&Number.isFinite(admissionPolicy.credit))app.innerHTML=app.innerHTML.replace(/<div class="card stat"><label>店铺信誉分<\/label>[\s\S]*?<\/strong><\/div>/,stat('店铺信誉分',Number(admissionPolicy.credit).toFixed(1)+'<span class="score-unit"> / 100</span>'));if(!admissionOpen()&&(current===1||current===2)){app.innerHTML=`<section class="card" style="margin-bottom:20px"><div class="cardhead"><h2>${esc(admissionPolicy.status)}</h2>${admissionPolicy.closureCauses?.deposit?'<span class="tag orange">联系客服补缴并解封</span>':''}${admissionPolicy.closureCauses?.order?'<span class="tag danger">订单超时需联系客服解封</span>':''}${action('联系客服','support()',true)}</div>${admissionPolicy.depositEnabled?`<div class="info"><div><label>应缴保证金</label>${money(admissionPolicy.required)}</div><div><label>待缴金额</label>${money(Math.max(0,admissionPolicy.required-admissionPolicy.balance))}</div></div>`:''}</section>`+app.innerHTML;app.innerHTML=app.innerHTML.replace(/<button ([^>]*?)onclick="listProduct\((\d+)\)"([^>]*?)>/g,'<button $1onclick="listProduct($2)"$3 disabled>')}};
